package net.officefloor.hq.app.person;

import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidatePerson {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PersonRequest request, Out<PersonRequest> body, Settings settings)
            throws InvalidPersonException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("Grade must be A, B or C");
        }
        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!gradeFrom.isEmpty()) {
            try {
                java.time.LocalDate.parse(gradeFrom);
            } catch (java.time.format.DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be a date");
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !terms.matches("\\d{1,6}")) {
            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more");
        }
        if (!terms.isEmpty()) {
            terms = String.valueOf(Integer.parseInt(terms));
        }
        String contact = request.contact() == null ? "" : request.contact().trim().toLowerCase(java.util.Locale.ROOT);
        body.set(new PersonRequest(name, grade, request.user(), request.version(), gradeFrom, terms, contact));
    }
}
package net.officefloor.hq.app.person;

/** Body of POST /api/sheets/{sheetId}/people and PUT /api/sheets/{sheetId}/people/{personId}.
 *  {@code version} (PUT only) is the version of the person the editor loaded; {@code gradeFrom}
 *  (PUT only, YYYY-MM-DD) is the date the grade is recorded from, blank for the sheet's today;
 *  {@code terms} is the person's own terms in whole days, blank for none; {@code contact} is the
 *  person's contact, trimmed and lower-cased, blank for none. */
public record PersonRequest(String name, String grade, String user, Integer version, String gradeFrom, String terms, String contact) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.plugin.variable.Val;

public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, People people)
            throws InvalidPersonException, PersonConflictException {
        if (request.version() != null && request.version() != person.getVersion()) {
            throw new PersonConflictException(person.getId());
        }
        // A person already clashing stays refused until renamed to a name that clashes nowhere in the tree (nor any alias).
        if (people.nameTaken(person.getSheetId(), request.name(), person.getId()) || people.wouldClash(person, request.name())) {
            throw new InvalidPersonException("The name is already in use");
        }
        if (!request.contact().isEmpty() && people.contactTaken(person.getSheetId(), request.contact(), person.getId())) {
            throw new InvalidPersonException("The contact is already in use");
        }
        person.setName(request.name());
        person.editTerms(request.terms().isEmpty() ? null : Integer.valueOf(request.terms()));
        person.editContact(request.contact().isEmpty() ? null : request.contact());
        // The form's grade is recorded from its from-date (the sheet's today when blank), keeping the
        // grades already recorded; a save leaving the grade as the row showed it with no from-date
        // records nothing.
        if (request.gradeFrom().isEmpty() && request.grade().equals(person.getGrade())) {
            return;
        }
        LocalDate from = request.gradeFrom().isEmpty() ? person.getToday() : LocalDate.parse(request.gradeFrom());
        person.recordGrade(from, request.grade());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PathVariable;

public class SavePersonCreated {
    public void save(@PathVariable("sheetId") String sheetId, @Val PersonRequest request, People people, Audit audit, @Val RollupFigures before, Rollup rollup,
            ObjectResponse<ResponseEntity<PersonResponse>> response) throws InvalidPersonException {
        if (people.nameTaken(sheetId, request.name(), null)) {
            throw new InvalidPersonException("The name is already in use");
        }
        if (!request.contact().isEmpty() && people.contactTaken(sheetId, request.contact(), null)) {
            throw new InvalidPersonException("The contact is already in use");
        }
        Person person = people.add(sheetId, request.name(), request.grade(),
                request.terms().isEmpty() ? null : Integer.valueOf(request.terms()),
                request.contact().isEmpty() ? null : request.contact());
        audit.recordOnCommit("PERSON_ADDED sheet=" + sheetId + " by=" + request.user()
                + " name=" + person.getName() + " grade=" + person.getGrade()
                + (person.getTerms() == null ? "" : " terms=" + person.getTerms())
                + (person.getContact() == null ? "" : " contact=" + person.getContact()));
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(new ResponseEntity<>(PersonResponse.from(person), HttpStatus.CREATED));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, People people) throws PersonConflictException {
        if (!people.save(person)) {
            throw new PersonConflictException(person.getId());
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person));
    }
}

